// Conecta BU -> agente de orientacion (RF-014, RN-011).
// El backend ya filtro crisis y preguntas clinicas (tambien en el historial) y
// envia solo el contexto autorizado: servicios con horarios libres, eventos,
// y las citas propias del estudiante. Aqui se arma la consulta a Gemini.
const secreto = $env.CONECTA_BU_SECRET || '';
const cabeceras = $json.headers || {};
if (secreto && cabeceras['x-conecta-bu-secret'] !== secreto) {
  throw new Error('Peticion rechazada: secreto invalido.');
}

const { pregunta = '', historial = [], usuario = {}, contexto = {}, reglas = '' } = $json.body || {};

const servicios = (contexto.servicios || [])
  .map((s) => {
    const horarios = s.proximosHorarios && s.proximosHorarios.length ? ` Próximos horarios libres: ${s.proximosHorarios.join('; ')}` : ' Sin horarios libres por ahora.';
    return `- ${s.nombre}${s.descripcion ? ': ' + s.descripcion : ''} (${s.horariosLibres ?? 0} horarios libres).${horarios}`;
  })
  .join('\n') || '- (sin servicios activos)';

const eventos = (contexto.eventos || [])
  .map((e) => `- ${e.nombre}: ${e.fecha}, de ${e.hora} | ${e.modalidad === 'Virtual' ? 'Virtual' : e.lugar}${e.modalidad === 'Hibrida' ? ' (también virtual)' : ''} | Cupos libres: ${e.cuposDisponibles ?? '?'} | ${e.inscrito ? 'El estudiante YA está inscrito.' : e.inscripcionAbierta ? 'Inscripciones abiertas.' : 'Inscripciones cerradas.'}`)
  .join('\n') || '- (sin eventos publicados)';

const citas = (contexto.misCitas || [])
  .map((c) => `- ${c.servicio}: ${c.fecha} a las ${c.hora} | ${c.sePuedeCancelar ? 'Aún se puede cancelar.' : 'Ya no se puede cancelar desde la plataforma (faltan menos de 24 horas).'}`)
  .join('\n') || '- (no tiene citas agendadas)';

const instrucciones = [
  'Eres el asistente de orientación de Conecta BU, la plataforma de Bienestar Universitario (Desarrollo Humano / Orientación) de la Uniautónoma del Cauca.',
  reglas,
  'Responde en máximo 5 frases, en español de Colombia, con tono cálido y respetuoso. Usa el nombre del estudiante solo de vez en cuando.',
  'Solo usa la información de abajo; si no la tienes, dilo y sugiere agendar una cita o acercarse a Bienestar. Nunca inventes fechas, horarios, enlaces ni datos.',
  'Cómo funciona la plataforma: «Pedir una cita» para elegir un horario libre (solo una cita activa a la vez); «Mis citas» para consultarla o cancelarla (mínimo 24 horas antes); «Talleres y eventos» para inscribirse mientras haya cupos; en los eventos virtuales el enlace de la reunión aparece en «Talleres y eventos» después de inscribirse.',
  `Hoy es ${contexto.hoy || 'sin dato'}.`,
  `Servicios de Orientación:\n${servicios}`,
  `Próximos talleres y eventos:\n${eventos}`,
  `Citas del estudiante:\n${citas}`,
].filter(Boolean).join('\n\n');

// Conversacion: Gemini espera turnos 'user' y 'model', empezando por 'user'.
const turnos = [];
for (const m of Array.isArray(historial) ? historial : []) {
  const role = m.autor === 'estudiante' ? 'user' : 'model';
  const texto = String(m.texto || '').slice(0, 600);
  if (!texto) continue;
  if (!turnos.length && role === 'model') continue;
  const ultimo = turnos[turnos.length - 1];
  if (ultimo && ultimo.role === role) ultimo.parts[0].text += '\n' + texto;
  else turnos.push({ role, parts: [{ text: texto }] });
}
const actual = `${usuario.nombre ? 'Estudiante: ' + usuario.nombre + '. ' : ''}Pregunta: ${pregunta}`;
const ultimo = turnos[turnos.length - 1];
if (ultimo && ultimo.role === 'user') ultimo.parts[0].text += '\n' + actual;
else turnos.push({ role: 'user', parts: [{ text: actual }] });

return [{ json: {
  cuerpoGemini: {
    systemInstruction: { parts: [{ text: instrucciones }] },
    contents: turnos,
    generationConfig: { temperature: 0.4, maxOutputTokens: 500 },
  },
} }];

// Toma el texto que devolvio Gemini y lo entrega con la forma que espera el backend: { respuesta }.
// Si Gemini bloqueo la respuesta por seguridad o no devolvio texto, se falla a proposito:
// el backend responde entonces con su base de conocimiento local.
const candidato = $json.candidates?.[0];
const partes = candidato?.content?.parts || [];
const respuesta = partes.map((p) => p.text || '').join('').trim();
if (!respuesta) {
  throw new Error(`Gemini no devolvio texto (${candidato?.finishReason || $json.promptFeedback?.blockReason || 'sin motivo'}).`);
}
return [{ json: { respuesta } }];
